package com.geotree.app.core.ai

import java.io.File
import java.io.FileNotFoundException
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assume.assumeTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder

/**
 * The model that ships in the APK (src/main/assets/leaf_model, generated by
 * backend/scripts/export_mobile_model.py) is complete, consistent and loads through the same
 * store the app uses. Skipped only on a checkout without the (gitignored) model; the APK build
 * itself refuses to package without it (verifyLeafModel).
 */
class BundledLeafModelTest {
    @get:Rule val temp = TemporaryFolder()

    private val assetRoot = File("src/main/assets")

    @Test
    fun `bundled model is complete and compatible`() {
        assumeTrue("bundled model not generated in this checkout", File(assetRoot, "leaf_model/manifest.json").isFile)
        val store = LeafModelStore({ path -> File(assetRoot, path).takeIf { it.isFile }?.inputStream() ?: throw FileNotFoundException(path) }, temp.newFolder())
        val manifest = store.manifest()
        assertNull(manifest.problem())
        assertEquals("dinov2_vits14", manifest.model)
        assertEquals("dinov2_vits14|336px|resize384-bicubic-centercrop|imagenet-norm|cls|v1", manifest.embeddingModel)
        assertEquals(336, manifest.preprocessing.imageSize)
        assertEquals(384, manifest.preprocessing.resizeShortSide)
        assertEquals(384, manifest.embeddingDimension)

        val model = store.prepare() // copies the ~87 MB backbone and verifies its SHA-256
        assertEquals(HeadSource.BUNDLED, model.headSource)
        assertEquals(manifest.backbone.bytes, model.backboneFile.length())
        assertNull(model.head.problemWith(manifest))
        assertEquals(listOf("Healthy", "Spotting", "Mold"), model.head.classes.map { it.name })
        // The export verified ONNX Runtime against the server's PyTorch features on every dataset image.
        val parity = File(assetRoot, "leaf_model/manifest.json").readText()
        assertEquals(true, parity.contains("\"classAgreement\": 1.0"))
    }
}
